/**
 * Right-side peek pane. Renders alongside the main content inside the owner
 * layout: when a peek item is open, the layout splits (main shrinks left, this
 * pane shows right). The body mounts the SAME content component the dedicated
 * page uses (see PeekPaneContent) — no duplication. Closes via the X or when
 * the user navigates the main column.
 */
export function NotificationPeekPane() {
	const peek = useNotificationPeek();
	if (!peek?.item) return null;
	return <PeekPaneSurface item={peek.item} onClose={peek.close} />;
}

function PeekPaneSurface({
	item,
	onClose,
}: {
	item: PeekItem;
	onClose: () => void;
}) {
	const destination = parseAppHref(item.href);
	return (
		<aside className="flex w-[460px] shrink-0 flex-col border-l border-border bg-background">
			<div className="flex h-11 shrink-0 items-center justify-between border-b border-border px-3">
				<Link
					to={destination.pathname as "/"}
					search={(destination.search ?? {}) as never}
					className="inline-flex items-center gap-1 text-xs font-medium text-muted-foreground transition-colors hover:text-foreground"
					onClick={onClose}
				>
					Open full page
					<ArrowUpRight className="h-3 w-3" />
				</Link>
				<Button
					type="button"
					variant="ghost"
					size="icon"
					className="size-7 shrink-0 text-muted-foreground hover:text-foreground"
					aria-label="Close preview"
					onClick={onClose}
				>
					<X className="h-4 w-4" />
				</Button>
			</div>
			<div className="min-h-0 flex-1 overflow-y-auto">
				<PeekPaneContent href={item.href} runId={item.runId} />
			</div>
		</aside>
	);
}
export function destinationHrefFromPeekSearch(
	owner: string,
	search: PeekSearch,
): string | null {
	if (search.peek_run_id && /^\d+$/.test(search.peek_run_id)) {
		const query = new URLSearchParams({
			run_ids: search.peek_run_id,
		});
		return `/${owner}/activity?${query.toString()}`;
	}

	if (search.peek_agent && search.peek_behavior) {
		const query = new URLSearchParams();
		if (search.peek_view === "activity" || search.peek_view === "definition") {
			query.set("view", search.peek_view);
		}
		if (
			search.peek_behavior_run_id &&
			/^\d+$/.test(search.peek_behavior_run_id)
		) {
			query.set("run_id", search.peek_behavior_run_id);
		}
		const suffix = query.size > 0 ? `?${query.toString()}` : "";
		return `/${owner}/agents/${search.peek_agent}/behaviors/${search.peek_behavior}${suffix}`;
	}

	return null;
}

/** Convert a peekable destination href into namespaced current-route search. */
export function peekSearchFromDestinationHref(href: string): PeekSearch | null {
	const { pathname, search } = parseAppHref(href);
	const segments = pathname.split("/").filter(Boolean);

	if (segments.length === 2 && segments[1] === "activity") {
		const runIds = search?.run_ids;
		if (!runIds || runIds.includes(",") || !/^\d+$/.test(runIds)) return null;
		return { peek: "1", peek_run_id: runIds };
	}

	if (
		segments.length === 5 &&
		segments[1] === "agents" &&
		segments[3] === "behaviors"
