/** Split an app href into path + search for TanStack Router. */
export function parseAppHref(href: string): {
	pathname: string;
	search: Record<string, string> | undefined;
} {
	let trimmed = href.trim();
	if (URL.canParse(trimmed)) {
		const absolute = new URL(trimmed);
		if (absolute.protocol === "http:" || absolute.protocol === "https:") {
			trimmed = `${absolute.pathname}${absolute.search}`;
		}
	}
	const q = trimmed.indexOf("?");
	if (q < 0) return { pathname: trimmed, search: undefined };
	const pathname = trimmed.slice(0, q) || "/";
	const params = new URLSearchParams(trimmed.slice(q + 1));
	const search: Record<string, string> = {};
	for (const [k, v] of params) {
		search[k] = v;
	}
	return {
		pathname,
		search: Object.keys(search).length > 0 ? search : undefined,
	};
}

/** Statuses that should render as failure in the activity feed. */
export function isFailedRunStatus(status: string): boolean {
	return status === "failed" || status === "timeout" || status === "error";
}
import { describe, expect, it } from "vitest";
import { isFailedRunStatus, parseAppHref } from "./activity-links";

describe("parseAppHref", () => {
	it("splits path and query", () => {
		expect(parseAppHref("/acme/memory?view=events&run_ids=198")).toEqual({
			pathname: "/acme/memory",
			search: { view: "events", run_ids: "198" },
		});
	});

	it("normalizes an absolute app URL before routing", () => {
		expect(
			parseAppHref(
				"https://app.lobu.ai/acme/agents/personal-agent/behaviors/71?view=activity",
			),
		).toEqual({
			pathname: "/acme/agents/personal-agent/behaviors/71",
			search: { view: "activity" },
		});
	});

	it("returns pathname only when no query", () => {
		expect(parseAppHref("/acme/connectors")).toEqual({
			pathname: "/acme/connectors",
			search: undefined,
		});
	});
});

describe("isFailedRunStatus", () => {
	it("treats timeout as failed", () => {
		expect(isFailedRunStatus("failed")).toBe(true);
